453	    /// The CLI's `finish_transaction`: reset git HEAD and export
454	    /// refs (colocated, retried on lockfile contention), commit the
455	    /// operation, update the working copy to the possibly-rewritten
456	    /// wc commit.
457	    pub fn finish_tx(&mut self, mut tx: Transaction, desc: &str) -> Result<()> {
458	        if !tx.repo().has_changes() {
459	            debug!("{desc}: nothing changed");
460	            return Ok(());
461	        }
462	        tx.repo_mut().rebase_descendants().block_on()?;
463	        let name = self.workspace.workspace_name().to_owned();
464	        let old_wc_commit = tx
465	            .base_repo()
466	            .view()
467	            .get_wc_commit_id(&name)
468	            .map(|id| tx.base_repo().store().get_commit(id))
469	            .transpose()?;
470	        let new_wc_commit_id = tx.repo().view().get_wc_commit_id(&name).cloned();
471	
472	        if self.colocated {
473	            retry_git_lock(|| {
474	                if let Some(id) = &new_wc_commit_id {
475	                    let wc_commit = tx.repo().store().get_commit(id)?;
476	                    git::reset_head(tx.repo_mut(), &wc_commit).block_on()?;
477	                }
478	                git::export_refs(tx.repo_mut())?;
479	                Ok(())
480	            })?;
481	        }
482	
483	        self.repo = tx.commit(desc).block_on()?;
484	
485	        if let Some(id) = &new_wc_commit_id {
486	            let new_wc_commit = self.repo.store().get_commit(id)?;
487	            let old_tree = old_wc_commit.as_ref().map(|c| c.tree());
488	            self.workspace
489	                .check_out(self.repo.op_id().clone(), old_tree.as_ref(), &new_wc_commit)
490	                .block_on()?;
491	        }
492	        Ok(())
493	    }
