520	    /// Snapshot the working copy, then update the wc commit's
521	    /// description and start a new empty change on top (`jj commit`).
522	    pub fn commit(&mut self, desc: &str) -> Result<()> {
523	        self.snapshot()?;
524	        let wc_commit = self.wc_commit()?;
525	        let name = self.workspace.workspace_name().to_owned();
526	        let mut tx = self.start_tx();
527	        let new_commit = tx
528	            .repo_mut()
529	            .rewrite_commit(&wc_commit)
530	            .set_description(complete_newline(desc))
531	            .write()
532	            .block_on()?;
533	        let new_wc_commit = tx
534	            .repo_mut()
535	            .new_commit(vec![new_commit.id().clone()], wc_commit.tree())
536	            .write()
537	            .block_on()?;
538	        tx.repo_mut().edit(name, &new_wc_commit).block_on()?;
539	        self.finish_tx(tx, &format!("commit {}", wc_commit.id().hex()))
540	    }
