623	    /// Snapshot, then push local bookmark `name` to `origin`
624	    /// (`jj git push --bookmark <name>`), force-with-lease against
625	    /// the last-seen remote position.
626	    ///
627	    /// Deviation from the CLI: no conflicted / no-description /
628	    /// private preflights on the pushed commits. The push callers
629	    /// validate the commit they publish before calling.
630	    pub fn git_push_bookmark(&mut self, name: &str) -> Result<()> {
631	        use jj_lib::git::{GitPushOptions, GitPushRefTargets, GitSettings};
632	        use jj_lib::merge::Diff;
633	        use jj_lib::ref_name::{RefNameBuf, RemoteName};
634	
635	        self.snapshot()?;
636	        let remote = RemoteName::new("origin");
637	        let ref_name: RefNameBuf = name.into();
638	        let local = self
639	            .repo
640	            .view()
641	            .get_local_bookmark(&ref_name)
642	            .as_normal()
643	            .cloned()
644	            .ok_or_else(|| format!("bookmark '{name}' is absent or conflicted"))?;
645	        let remote_ref = self
646	            .repo
647	            .view()
648	            .get_remote_bookmark(ref_name.to_remote_symbol(remote));
649	        let before = remote_ref.target.as_normal().cloned();
650	        if before.as_ref() == Some(&local) {
651	            return Ok(()); // Already in sync; matches `jj git push` "Nothing changed".
652	        }
653	        let ref_updates = GitPushRefTargets {
654	            bookmarks: vec![(
655	                ref_name.clone(),
656	                Diff {
657	                    before,
658	                    after: Some(local),
659	                },
660	            )],
661	            tags: vec![],
662	        };
663	        let git_settings = GitSettings::from_settings(&self.settings)?;
664	        let mut tx = self.start_tx();
665	        let stats = git::push_refs(
666	            tx.repo_mut(),
667	            git_settings.to_subprocess_options(),
668	            remote,
669	            &ref_updates,
670	            &mut DebugCallback,
671	            &GitPushOptions::default(),
672	        )?;
673	        if !stats.all_ok() {
674	            return Err(format!(
675	                "git push of bookmark '{name}' failed: rejected {:?}, remote rejected {:?}",
676	                stats.rejected, stats.remote_rejected
677	            )
678	            .into());
679	        }
680	        self.finish_tx(tx, &format!("push bookmark {name} to git remote origin"))
681	    }
