683	    /// Snapshot, then fetch all branches from `remote` and import
684	    /// the results (`jj git fetch --remote <remote>`). Returns one
685	    /// line per changed remote bookmark, empty when the fetch
686	    /// changed nothing.
687	    ///
688	    /// Deviation from the CLI: the branch expression is always "all
689	    /// branches" rather than the remote's configured fetch refspecs,
690	    /// which is what a standard `origin` resolves to anyway.
691	    pub fn git_fetch(&mut self, remote: &str) -> Result<Vec<String>> {
692	        use jj_lib::git::{GitFetch, GitFetchRefExpression, GitSettings, expand_fetch_refspecs};
693	        use jj_lib::ref_name::RemoteName;
694	        use jj_lib::str_util::StringExpression;
695	
696	        self.snapshot()?;
697	        let remote = RemoteName::new(remote);
698	        let expanded = expand_fetch_refspecs(
699	            remote,
700	            GitFetchRefExpression {
701	                bookmark: StringExpression::all(),
702	                tag: StringExpression::none(),
703	            },
704	        )?;
705	        let git_settings = GitSettings::from_settings(&self.settings)?;
706	        let import_options = self.import_options()?;
707	        let mut tx = self.start_tx();
708	        let mut fetch = GitFetch::new(
709	            tx.repo_mut(),
710	            git_settings.to_subprocess_options(),
711	            &import_options,
712	        )?;
713	        fetch.fetch(remote, expanded, &mut DebugCallback, None)?;
714	        let stats = fetch.import_refs().block_on()?;
715	        drop(fetch);
716	        let lines: Vec<String> = stats
717	            .changed_remote_bookmarks
718	            .iter()
719	            .map(|update| format!("bookmark {} updated", update.symbol))
720	            .collect();
721	        if !tx.repo().has_changes() {
722	            return Ok(lines);
723	        }
724	        tx.repo_mut().rebase_descendants().block_on()?;
725	        self.finish_tx(tx, &format!("fetch from git remote {}", remote.as_str()))?;
726	        Ok(lines)
727	    }
728	}
