730	/// Attempts per lock-contended git write. The doubling backoff
731	/// starting at `LOCK_RETRY_START` waits 25 + 50 + 100 + 200 ms,
732	/// about 375 ms in total, before the last try.
733	const LOCK_RETRY_ATTEMPTS: u32 = 5;
734	
735	/// First backoff delay. Each subsequent retry doubles it.
736	const LOCK_RETRY_START: Duration = Duration::from_millis(25);
737	
738	/// True when `e` is, or wraps anywhere in its source chain, a git
739	/// lockfile-acquisition failure (`gix::lock::acquire::Error`): the
740	/// transient "could not acquire lock for '.git/index'" class of
741	/// bugs.md #1.
742	///
743	/// Classification is by type, never by message substring. The
744	/// narrow downcast is the point: it can only be produced by a local
745	/// lockfile grab, so never-retryable failures (a missing git binary
746	/// via `GitSubprocessError::SpawnInPath`, an old git via
747	/// `UnsupportedGitOption`, a remote rejection) classify false
748	/// without being named, where a broader "retry git errors" rule
749	/// would loop on them forever.
750	fn is_lock_contention(e: &(dyn std::error::Error + 'static)) -> bool {
751	    let mut cur = Some(e);
752	    while let Some(err) = cur {
753	        if err.downcast_ref::<gix::lock::acquire::Error>().is_some() {
754	            return true;
755	        }
756	        cur = err.source();
757	    }
758	    false
759	}
760	
761	/// Run `f`, retrying on git lockfile contention with a short
762	/// doubling backoff: the in-process home of the bugs.md #1 fix (gix
763	/// gives the lock one attempt, so the retry loop is ours to own).
764	///
765	/// Callers wrap only git writes that precede the transaction
766	/// commit, so a retried closure never doubles an op-store write.
767	fn retry_git_lock<T>(mut f: impl FnMut() -> Result<T>) -> Result<T> {
768	    let mut delay = LOCK_RETRY_START;
769	    for attempt in 1..LOCK_RETRY_ATTEMPTS {
770	        match f() {
771	            Err(e) if is_lock_contention(e.as_ref()) => {
772	                debug!("git lockfile contended (attempt {attempt}): {e}; retrying in {delay:?}");
773	                std::thread::sleep(delay);
774	                delay *= 2;
775	            }
776	            other => return other,
777	        }
778	    }
779	    f()
780	}
