911	    /// Contention that never clears is reported after the attempt
912	    /// budget, not looped forever.
913	    #[test]
914	    fn retry_git_lock_gives_up_after_budget() {
915	        let mut calls = 0;
916	        let got: Result<()> = retry_git_lock(|| {
917	            calls += 1;
918	            Err(Box::new(lock_error()) as Box<dyn std::error::Error>)
919	        });
920	        assert!(got.is_err());
921	        assert_eq!(calls, LOCK_RETRY_ATTEMPTS);
922	    }
923	}
