1	//! Integration tests for the sync module.
2	//!
3	//! End-to-end tests for `sync_repos` against real dual-repo jj
4	//! fixtures. Each test builds an isolated fixture (bare-git
5	//! remotes + colocated jj repos) under a unique tempdir via
6	//! `Fixture::new`, then drives the scenario with plain `jj`
7	//! subprocess calls. Requires `jj` in `PATH`.
8	//!
9	//! Fixtures clean themselves up via `Fixture`'s `Drop` impl so a
10	//! panicking test still removes its tempdir.
11	
12	use super::*;
13	use crate::options_flags::scope::Side;
14	use crate::test_helpers::{Fixture, cid, jj_ok, test_ctx};
15	use std::fs;
16	use std::process::Command;
17	
18	use crate::common::{default_scope, find_workspace_root_from, scope_to_repos};
19	use crate::jj::{current_op_id, op_restore};
20	
21	/// Resolver helpers must consume what `init --repo-local` produces.
22	///
23	/// Builds a real dual-repo fixture (bare git remotes + colocated jj
24	/// repos + the canonical `.vc-config.toml` pair init writes), then
25	/// drives the resolver chain `sync()` uses when `-R` is empty:
26	///
27	/// - `find_workspace_root_from(&fx.bot)` walks up to `fx.work`
28	///   (proves cwd-portability against init's `path = "/.claude"` /
29	///   `path = "/"` config split).
30	/// - `default_scope(Some(&fx.work))` reads the workspace config and
31	///   resolves to the dual-repo default.
32	/// - `scope_to_repos` maps each `Scope` shape to the right
33	///   absolute path(s) under the fixture.
34	///
35	/// Pure check on the resolver chain: does not invoke `sync()`
36	/// itself, since that walks `std::env::current_dir()` and parallel
37	/// `cargo test` makes cwd mutation unsafe.
38	#[test]
39	fn resolver_chain_against_init_repo_local() {
40	    let fx = Fixture::new("resolver-chain");
41	
42	    // Walk-up from the bot side lands on the work root.
43	    assert_eq!(
44	        find_workspace_root_from(&fx.bot).as_deref(),
45	        Some(&*fx.work),
46	        "find_workspace_root should resolve from .claude up to work"
47	    );
48	    // Walk-up from the work root finds itself.
49	    assert_eq!(
50	        find_workspace_root_from(&fx.work).as_deref(),
51	        Some(&*fx.work)
52	    );
53	
54	    // init writes bot = "/.claude", so the
55	    // workspace's default scope is dual.
56	    assert_eq!(
57	        default_scope(Some(&fx.work)),
58	        Scope(vec![Side::Work, Side::Bot])
59	    );
60	
61	    // Each scope shape resolves to the right absolute path(s).
62	    assert_eq!(
63	        scope_to_repos(&Scope(vec![Side::Work, Side::Bot]), Some(&fx.work)).unwrap(),
64	        vec![fx.work.clone(), fx.bot.clone()]
65	    );
66	    assert_eq!(
67	        scope_to_repos(&Scope(vec![Side::Work]), Some(&fx.work)).unwrap(),
68	        vec![fx.work.clone()]
69	    );
70	    assert_eq!(
71	        scope_to_repos(&Scope(vec![Side::Bot]), Some(&fx.work)).unwrap(),
72	        vec![fx.bot.clone()]
73	    );
74	
75	    // sync_repos accepts the resolved list and reports up-to-date:
76	    // the resolver's output is shaped the way sync expects.
77	    let resolved = scope_to_repos(&Scope(vec![Side::Work, Side::Bot]), Some(&fx.work)).unwrap();
78	    sync_repos(&mut test_ctx(), &resolved, &default_params())
79	        .expect("sync should succeed on resolved repos");
80	}
81	
82	/// Default sync params (the normal atomic sync, no flags).
83	///
84	/// Integration tests pass explicit repo paths through `sync_repos`
85	/// directly, so `repo` / `scope` stay `None` here and the CLI-side
86	/// default resolution is not exercised by this helper.
87	fn default_params() -> SyncParams {
88	    SyncParams {
89	        check: false,
90	        quiet: false,
91	        bookmark: "main".to_string(),
92	        remote: "origin".to_string(),
93	        rebase: false,
94	        repo: None,
95	        scope: None,
96	    }
97	}
98	
99	/// Default params with `--rebase` set (auto-confirm the work-repo
100	/// non-empty `@` rebase).
101	fn rebase_params() -> SyncParams {
102	    SyncParams {
103	        rebase: true,
104	        ..default_params()
105	    }
106	}
107	
108	/// True when `revset` matches at least one commit in `repo`.
109	fn has(repo: &Path, revset: &str) -> bool {
110	    !jj_ok(
111	        repo,
112	        &[
113	            "log",
114	            "-r",
115	            revset,
116	            "--no-graph",
117	            "-T",
118	            r#"commit_id.short(12) ++ "\n""#,
119	        ],
120	    )
121	    .trim()
122	    .is_empty()
123	}
124	
125	/// Add a local-only commit on `main` in `repo` (not pushed), then
126	/// restore `@` to an empty child so pre-flight still passes.
127	///
128	/// Sequence: write file -> describe `@` -> advance `main` to `@` ->
129	/// create a fresh empty `@` above it.
130	fn add_local_commit(repo: &Path, file: &str, content: &str, msg: &str) {
131	    fs::write(repo.join(file), content).expect("write local file");
132	    jj_ok(repo, &["describe", "@", "-m", msg]);
133	    jj_ok(repo, &["bookmark", "set", "main", "-r", "@"]);
134	    jj_ok(repo, &["new"]);
135	}
136	
137	/// Clone `remote_url` into `<base>/<work_name>` (colocated) and
138	/// return the new workdir.
139	fn clone(base: &Path, remote_url: &Path, work_name: &str) -> PathBuf {
140	    let workdir = base.join(work_name);
141	    let out = Command::new("jj")
142	        .args(["git", "clone", "--colocate"])
143	        .arg(remote_url)
144	        .arg(&workdir)
145	        .output()
146	        .expect("spawn jj clone");
147	    assert!(
148	        out.status.success(),
149	        "jj git clone failed: {}",
150	        String::from_utf8_lossy(&out.stderr)
151	    );
152	    workdir
153	}
154	
155	/// Clone `remote_url` into `<base>/<work_name>`, add a commit, push it.
156	///
157	/// Used to make the remote advance beyond the fixture's `main`
158	/// from a separate working copy. Returns the pushed commit's id.
159	fn push_from_clone(
160	    base: &Path,
161	    remote_url: &Path,
162	    work_name: &str,
163	    file: &str,
164	    content: &str,
165	    msg: &str,
166	) -> String {
167	    let workdir = clone(base, remote_url, work_name);
168	    fs::write(workdir.join(file), content).expect("write remote file");
169	    jj_ok(&workdir, &["describe", "@", "-m", msg]);
170	    jj_ok(&workdir, &["bookmark", "set", "main", "-r", "@"]);
171	    jj_ok(&workdir, &["git", "push", "--bookmark", "main"]);
172	    cid(&workdir, "main")
173	}
174	
175	/// Scenario 1: fresh fixture, nothing to do: `sync` leaves both
176	/// repos untouched and persists nothing (no `.vc-x1/` state, and
177	/// the pre-sync snapshots live and die with the invocation).
178	#[test]
179	fn sync_up_to_date() {
180	    let fx = Fixture::new("up-to-date");
181	    let work_main = cid(&fx.work, "main");
182	    let bot_main = cid(&fx.bot, "main");
183	    sync_repos(&mut test_ctx(), &fx.repos(), &default_params()).expect("sync should succeed");
184	    assert_eq!(cid(&fx.work, "main"), work_main);
185	    assert_eq!(cid(&fx.bot, "main"), bot_main);
186	    assert!(
187	        !fx.work.join(".vc-x1").exists(),
188	        "no state persisted (work)"
189	    );
190	    assert!(!fx.bot.join(".vc-x1").exists(), "no state persisted (bot)");
191	}
192	
193	/// Scenario 2a: a non-empty `@` on top of main (simulates `/exit`
194	/// trailing session writes in `.claude`) when there's nothing new on
195	/// the remote. `@-` is already the main tip, so reposition no-ops:
196	/// `@` keeps its chid and the trailing writes stay in the working
197	/// copy, no sibling head, no `jj new` churn.
198	#[test]
199	fn sync_bot_noop_when_up_to_date() {
200	    let fx = Fixture::new("bot-noop-uptodate");
201	    let pre_main = cid(&fx.bot, "main");
202	    fs::write(fx.bot.join("trailing.jsonl"), "{\"line\":1}\n").expect("write trailing file");
203	    let pre_at = jj_ok(
204	        &fx.bot,
205	        &["log", "-r", "@", "--no-graph", "-T", "change_id.short(12)"],
206	    );
207	    sync_repos(&mut test_ctx(), &fx.repos(), &default_params()).expect("sync should succeed");
208	    // main didn't move.
209	    assert_eq!(cid(&fx.bot, "main"), pre_main, "main should not move");

