/// - `name`: repo name used by the README rewrite.
pub fn prepare_local_repo(
    target: &Path,
    info_label: &str,
    template: Option<&Path>,
    name: &str,
) -> Result<(), Box<dyn std::error::Error>> {
    info!(
        "Preparing local repo {info_label} directory at {}",
        target.display()
    );

    if let Some(parent) = target.parent() {
        mkdir_p(parent)?;
    }
    mkdir_p(target)?;

    // `jj git init --colocate` creates the git repo itself: the
    // former explicit `git init` was redundant (0.76.0-5).
    info!("Initializing {info_label} repo (jj, colocated)...");
    run("jj", &["git", "init", "--colocate"], target)?;

    if let Some(t) = template {
        info!(
            "Copying {info_label} template: {} -> {}",
            t.display(),
            target.display()
        );
        copy_template_recursive(t, target)?;
        rewrite_readme_first_line(target, name)?;
    }

    Ok(())
}

