88	/// Run an operation with retries, sleeping between attempts.
89	fn retry_op<T>(
90	    retry: &PushRetryOptions,
91	    mut op: impl FnMut() -> Result<T, Box<dyn std::error::Error>>,
92	) -> Result<T, Box<dyn std::error::Error>> {
93	    let mut last_err = String::new();
94	    for attempt in 1..=retry.push_retries {
95	        match op() {
96	            Ok(out) => {
97	                if attempt > 1 {
98	                    debug!("succeeded after {attempt} attempts");
99	                }
100	                return Ok(out);
101	            }
102	            Err(e) => {
103	                last_err = e.to_string();
104	                if attempt < retry.push_retries {
105	                    debug!(
106	                        "attempt {attempt}/{} failed: {last_err}",
107	                        retry.push_retries
108	                    );
109	                    debug!("retrying in {}s...", retry.push_retry_delay);
110	                    std::thread::sleep(std::time::Duration::from_secs(retry.push_retry_delay));
111	                }
112	            }
113	        }
114	    }
115	    Err(format!("failed after {} attempts: {last_err}", retry.push_retries).into())
116	}
