128	/// created is removed, best-effort, so a rerun isn't blocked by
129	/// the partial clone.
130	pub fn git_clone_colocated(source: &str, target: &Path) -> Result<()> {
131	    // Absolutize a local-path source against the caller's cwd
132	    // before it lands in `.git/config` (the CLI's
133	    // `absolute_git_url`): later fetches resolve the stored URL
134	    // against the repo dir, not the cwd the user typed it in
