1	//! Shared harness for CLI subprocess integration tests.
2	//!
3	//! Lives under `tests/common/` so Cargo treats it as a shared module
4	//! (a top-level `tests/common.rs` would be compiled as its own test
5	//! crate). Each `tests/<name>.rs` declares `mod common;` to opt in.
6	//!
7	//! Cargo compiles each `tests/*.rs` as its own crate, so helpers used
8	//! by some test crates but not others get dead-code warnings in the
9	//! crates that don't reach them. The crate-level allow below mutes
10	//! that: it's the standard idiom for shared `tests/common/`.
11	//!
12	//! - `vc_x1()` returns a `Command` for the binary Cargo built for
13	//!   the current test crate, resolved via the
14	//!   `CARGO_BIN_EXE_<bin-name>` env var with the name derived
15	//!   from `CARGO_PKG_NAME`: rename-proof, see Cargo.toml.
16	//! - `run_ok` / `run_err` wrap `Command::output` with a panic on
17	//!   the unexpected exit status, embedding stdout/stderr in the
18	//!   message so failures are debuggable.
19	//! - `CliFixture` owns a per-test tempdir under `$TMPDIR` and
20	//!   removes it on drop. Subprocesses get `HOME` overridden to a
21	//!   tempdir-scoped path so user config can't leak into or out of
22	//!   the test.
23	
24	#![allow(dead_code)]
25	
26	use std::path::{Path, PathBuf};
27	use std::process::{Command, Output};
28	use std::sync::atomic::{AtomicU64, Ordering};
29	use std::time::{SystemTime, UNIX_EPOCH};
30	
31	// Single source of truth for tempdir-root resolution, shared with
32	// the binary's unit-test harness via `#[path]` include. See
33	// `src/test_tmp_root.rs` for the rationale and dependency-free
34	// constraint.
35	#[path = "../../src/test_tmp_root.rs"]
36	mod test_tmp_root;
37	use test_tmp_root::{resolve_tmp_root, should_keep_tempdir};
38	
39	static COUNTER: AtomicU64 = AtomicU64::new(0);
40	
41	/// Build a unique tempdir path for a CLI test.
42	///
43	/// Mirrors `src/test_helpers::unique_base`'s shape (timestamp +
44	/// per-process counter) but uses a `vc-x1-cli-test-` prefix to
45	/// distinguish from the in-process fixtures' `vc-x1-test-` paths.
46	pub fn unique_base(tag: &str) -> PathBuf {
47	    let ts = SystemTime::now()
48	        .duration_since(UNIX_EPOCH)
49	        .map(|d| d.as_nanos())
50	        .unwrap_or(0);
51	    let n = COUNTER.fetch_add(1, Ordering::SeqCst);
52	    resolve_tmp_root().join(format!("vc-x1-cli-test-{tag}-{ts}-{n}"))
53	}
54	
55	/// Build a `Command` invoking the binary that Cargo built for
56	/// this test crate. Cargo sets `CARGO_BIN_EXE_<bin-name>` to the
57	/// full path of the freshly-built binary, and the var name is built
58	/// from `CARGO_PKG_NAME` (the default bin name is the package
59	/// name) so a Cargo.toml rename needs no edit here.
60	pub fn vc_x1() -> Command {
61	    // Allowlist entry 4 (clippy.toml): the CLI tests' launcher.
62	    // Spawning the built binary is what a CLI test is.
63	    #[allow(clippy::disallowed_methods)]
64	    Command::new(env!(concat!("CARGO_BIN_EXE_", env!("CARGO_PKG_NAME"))))
65	}
66	
67	/// Run `cmd`, panicking with stdout/stderr if it does not exit 0.
68	pub fn run_ok(cmd: &mut Command) -> Output {
69	    let out = cmd.output().expect("spawn vc-x1");
70	    if !out.status.success() {
71	        panic!(
72	            "vc-x1 unexpectedly failed: status={:?}\n--- stdout ---\n{}\n--- stderr ---\n{}",
73	            out.status,
74	            String::from_utf8_lossy(&out.stdout),
75	            String::from_utf8_lossy(&out.stderr),
76	        );
77	    }
78	    out
79	}
80	
81	/// Run `cmd`, panicking with stdout/stderr if it exits 0.
82	pub fn run_err(cmd: &mut Command) -> Output {
83	    let out = cmd.output().expect("spawn vc-x1");
84	    if out.status.success() {
85	        panic!(
86	            "vc-x1 unexpectedly succeeded\n--- stdout ---\n{}\n--- stderr ---\n{}",
87	            String::from_utf8_lossy(&out.stdout),
88	            String::from_utf8_lossy(&out.stderr),
89	        );
90	    }
91	    out
92	}
93	
94	/// RAII tempdir owner for CLI tests.
95	///
96	/// - `base` is a freshly-allocated unique tempdir, which does *not*
97	///   exist on disk until the caller (or the subprocess) creates it.
98	/// - `home` is a sibling under `base` reserved for `HOME` override
99	///   on subprocesses, so config reads don't escape the fixture.
100	/// - `Drop` removes the whole `base` tree (best-effort).
101	pub struct CliFixture {
102	    pub base: PathBuf,
103	    pub home: PathBuf,
104	}
105	
106	impl CliFixture {
107	    /// Allocate a fresh fixture, creating `home/` so `HOME=...` points
108	    /// at a real directory, and seed it with a jj user identity.
109	    ///
110	    /// The identity is required, not cosmetic: since 0.76.0-5 init
111	    /// publishes with `jj git push`, which refuses commits that
112	    /// have no author/committer, and the isolated `HOME` has no
113	    /// user config to inherit one from.
114	    pub fn new(tag: &str) -> Self {
115	        let base = unique_base(tag);
116	        let home = base.join("home");
117	        std::fs::create_dir_all(&home).expect("mkdir cli fixture home");
118	        let jj_cfg = home.join(".config").join("jj");
119	        std::fs::create_dir_all(&jj_cfg).expect("mkdir cli fixture jj config dir");
120	        std::fs::write(
121	            jj_cfg.join("config.toml"),
122	            "[user]\nname = \"cli-test\"\nemail = \"cli-test@example.com\"\n",
123	        )
124	        .expect("write cli fixture jj config");
125	        CliFixture { base, home }
126	    }
127	
128	    /// Build a `vc-x1` `Command` with `HOME` pointed at the
129	    /// fixture's isolated home dir, so user config can't leak.
130	    pub fn cmd(&self) -> Command {
131	        let mut c = vc_x1();
132	        c.env("HOME", &self.home);
133	        c
134	    }
135	
136	    /// Convenience: join a relative path under `base`.
137	    pub fn path(&self, rel: impl AsRef<Path>) -> PathBuf {
138	        self.base.join(rel)
139	    }
140	}
141	
142	impl Drop for CliFixture {
143	    /// Remove the fixture tree on drop. Suppressed when
144	    /// `$VC_X1_TEST_KEEP` is set: see
145	    /// `test_tmp_root::should_keep_tempdir`.
146	    fn drop(&mut self) {
147	        if should_keep_tempdir() {
148	            eprintln!("VC_X1_TEST_KEEP set; preserving {}", self.base.display());
149	        } else {
150	            let _ = std::fs::remove_dir_all(&self.base);
151	        }
152	    }
153	}
154	
155	/// Run `jj <args>` in `dir` (inspection only) with `HOME` pointed
156	/// at the fixture's isolated home, asserting success and returning
157	/// trimmed stdout.
158	///
159	/// The `HOME` + `current_dir` shape (vs the in-crate
160	/// `test_helpers::jj_ok`'s `-R` form) is deliberate: CLI tests
161	/// isolate the jj user config under the fixture home, and this
162	/// crate can't reach the binary's `test_helpers` module.
163	pub fn jj(home: &Path, dir: &Path, args: &[&str]) -> String {
164	    // Allowlist entry 4 (clippy.toml): test-helper jj inspection
165	    // under the fixture's isolated home.
166	    #[allow(clippy::disallowed_methods)]
167	    let out = Command::new("jj")
168	        .args(args)
169	        .env("HOME", home)
170	        .current_dir(dir)
171	        .output()
172	        .expect("spawn jj");
173	    assert!(
174	        out.status.success(),
175	        "jj {args:?} failed in {}: {}",
176	        dir.display(),
177	        String::from_utf8_lossy(&out.stderr)
178	    );
179	    String::from_utf8_lossy(&out.stdout).trim().to_string()
180	}
