183	pub fn cid(home: &Path, repo: &Path, rev: &str) -> String {
184	    jj(
185	        home,
186	        repo,
187	        &["log", "-r", rev, "--no-graph", "-T", "commit_id.short(12)"],
188	    )
189	}

